"""Render the reviewed, fail-closed routing overlay. Does not deploy anything."""
import json
import pathlib
import re

ROOT = pathlib.Path(__file__).resolve().parents[1]
POLICY = ROOT / 'deployment/cloudzy/android-8018-access.json'


def render():
    policy = json.loads(POLICY.read_text())
    assert policy['build'] == '8018'
    lines = [
        '# Generated by scripts/render-android-access.py; http context only.',
        '# This is an additional client routing restriction, not financial authorization.',
        'map $http_x_dt_version_code $dt_8018_client { default 0; 8018 1; }',
        'map "$request_method:$uri" $dt_8018_account_route {',
        ' default 0;',
    ]
    for pattern in policy['allowed']:
        assert '"' not in pattern and '\n' not in pattern and ';' not in pattern
        re.compile('^' + pattern + '$')
        lines.append(' "~^' + pattern + '$" 1;')
    lines.extend([
        '}',
        'map "$dt_8018_client:$dt_8018_account_route" $dt_8018_blocked {',
        ' default 0;',
        ' "1:0" 1;',
        '}',
        '',
    ])
    return '\n'.join(lines)


if __name__ == '__main__':
    rendered=render()
    (ROOT / 'deployment/cloudzy/android-8018-access.map.conf').write_text(rendered, newline='\n')
    template=ROOT / 'deployment/cloudzy/nginx.conf'
    content=template.read_text()
    start='# BEGIN GENERATED ANDROID 8018 ACCOUNT ACCESS\n'
    end='# END GENERATED ANDROID 8018 ACCOUNT ACCESS\n'
    block=start+rendered+end
    if start in content:
        left,tail=content.split(start,1);_,right=tail.split(end,1)
        content=left+block+right
    else:
        first,rest=content.split('\n',1);content=first+'\n'+block+rest
    template.write_text(content,newline='\n')
